/* R123H_THREE_VIEW_SCROLL_CLEARANCE_BEGIN: 44px buttons plus the thin
 * horizontal scrollbar need 52px inside the same adopted 56px header.
 * Narrow headers already use scrollbar-width:none and retain two 44px rows.
 */
@media (min-width: 561px) {
  body.v3-mode .topbar { grid-template-rows: 52px; padding-block: 2px; }
  body.v3-mode .topbar > #viewToolbar { height: 52px; min-height: 52px; }
}
/* R123H_THREE_VIEW_SCROLL_CLEARANCE_END */
